import org.springframework.web.bind.annotation.RestController;

/** Deposits a client pays up front, before any invoice. */
@RestController
@RequestMapping("/api/clients/{clientId}/deposits")
public class ClientDepositController {

    private final DepositService service;
    private final PaymentService payments;

    public ClientDepositController(DepositService service, PaymentService payments) {
        this.service = service;
        this.payments = payments;
    }

    @GetMapping
    public ClientDepositsResponse list(@PathVariable Long clientId) {
        return service.list(clientId);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public DepositResponse record(@PathVariable Long clientId, @Valid @RequestBody DepositRequest request) {
        return service.record(clientId, request);
    }

    /** Puts part of the client's held deposits toward their invoices, split across them. */
    @PostMapping("/applications")
    @ResponseStatus(HttpStatus.CREATED)
    public DepositApplicationResponse apply(@PathVariable Long clientId,
            @Valid @RequestBody DepositApplicationRequest request) {
        return payments.applyDeposits(clientId, request);
    }
}
package net.officefloor.hq.app.deposit;

import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.client.ClientRepository;
import net.officefloor.hq.app.payment.ClientPaymentRepository;
import net.officefloor.hq.app.refund.RefundRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class DepositService {

    private final DepositRepository deposits;
    private final DepositApplicationRepository applications;
    private final RefundRepository refunds;
    private final ClientPaymentRepository clientPayments;
    private final ClientRepository clients;
    private final Audit audit;

    public DepositService(DepositRepository deposits, DepositApplicationRepository applications,
            RefundRepository refunds, ClientPaymentRepository clientPayments, ClientRepository clients, Audit audit) {
        this.deposits = deposits;
        this.applications = applications;
        this.refunds = refunds;
        this.clientPayments = clientPayments;
        this.clients = clients;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public ClientDepositsResponse list(Long clientId) {
        requireClient(clientId);
        List<DepositResponse> held = deposits.findByClientIdOrderByDateAscIdAsc(clientId).stream()
                .map(DepositResponse::from).toList();
        BigDecimal paid = held.stream().map(DepositResponse::amount)
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        // Overpayments kept as credit are held alongside the deposits; deposits used up by payments count as applied.
        BigDecimal overpaid = clientPayments.sumToCreditByClientId(clientId).setScale(2);
        BigDecimal applied = applications.sumAmountByClientId(clientId)
                .add(clientPayments.sumFromDepositsByClientId(clientId)).setScale(2);
        BigDecimal refunded = refunds.sumFromDepositsByClientId(clientId).setScale(2);
        return new ClientDepositsResponse(paid.add(overpaid).subtract(applied).subtract(refunded), applied, refunded,
                held);
    }

    /** Records money a client paid up front, before any invoice; it is held against the client. */
    @Transactional
    public DepositResponse record(Long clientId, DepositRequest request) {
        requireClient(clientId);
        Deposit saved = deposits.saveAndFlush(new Deposit(clientId, request.amount(), request.date()));
        audit.record("DEPOSIT_RECORDED id=" + saved.getId() + " client=" + clientId
                + " amount=" + saved.getAmount().toPlainString());
        return DepositResponse.from(saved);
    }

    private void requireClient(Long clientId) {
        if (!clients.existsById(clientId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
        }
    }
}
-- Money a client pays up front, before any invoice. It is held against the client.
CREATE TABLE deposit (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id BIGINT         NOT NULL,
    amount    DECIMAL(12, 2) NOT NULL,
    paid_date DATE           NOT NULL,
    CONSTRAINT deposit_client_fk FOREIGN KEY (client_id) REFERENCES client (id),
    CONSTRAINT deposit_amount_positive CHECK (amount > 0)
);

CREATE INDEX deposit_client_idx ON deposit (client_id, paid_date);
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Truncate the audit file (called by /__test__/reset for per-spec isolation). */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

