import { Component, inject, input, signal } from '@angular/core';
import { MoneyPipe } from '../currencies/money.pipe';
import { rxResource } from '@angular/core/rxjs-interop';
import { NonNullableFormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { CurrencyCode } from '../clients/client.service';
import { DepositService } from './deposit.service';

const TWO_DECIMALS = /^\d+(\.\d{1,2})?$/;

// The deposits a client has paid up front, before any invoice, with what is still held, how much has been put toward invoices or refunded, and a form to record another.
@Component({
  selector: 'app-client-deposits',
  imports: [MoneyPipe, ReactiveFormsModule],
  template: `
    <section aria-labelledby="client-deposits-heading" data-testid="client-deposits">
      <h2 id="client-deposits-heading">Deposits</h2>
      @if (deposits.error()) {
        <p role="alert" data-testid="client-deposits-error">Could not load the client's deposits.</p>
      } @else if (deposits.hasValue()) {
        <p>
          Held: <span data-testid="client-deposit-total">{{ deposits.value().total | money: currency() }}</span>
        </p>
        @if (deposits.value().applied > 0) {
          <p>
            Put toward invoices:
            <span data-testid="client-deposit-applied">{{ deposits.value().applied | money: currency() }}</span>
          </p>
        }
        @if (deposits.value().refunded > 0) {
          <p>
            Refunded:
            <span data-testid="client-deposit-refunded">{{ deposits.value().refunded | money: currency() }}</span>
          </p>
        }
        @if (deposits.value().deposits.length > 0) {
          <ul data-testid="client-deposit-list">
            @for (d of deposits.value().deposits; track d.id) {
              <li [attr.data-testid]="'client-deposit-' + d.id">
                <span data-testid="client-deposit-date">{{ d.date }}</span>:
                <span data-testid="client-deposit-amount">{{ d.amount | money: currency() }}</span>
              </li>
            }
          </ul>
        }
      }
      <form [formGroup]="form" (ngSubmit)="submit()" data-testid="deposit-form" novalidate>
        <div>
          <label for="deposit-amount">Deposit amount</label>
          <input
            id="deposit-amount"
            type="number"
            inputmode="decimal"
            min="0.01"
            step="0.01"
            formControlName="amount"
            data-testid="deposit-form-amount"
            [attr.aria-invalid]="invalid('amount')"
            [attr.aria-describedby]="invalid('amount') ? 'deposit-amount-error' : null"
          />
          @if (invalid('amount')) {
            <p id="deposit-amount-error" role="alert" data-testid="deposit-form-amount-error">
              Enter an amount greater than zero with at most two decimal places.
            </p>
          }
        </div>
        <div>
          <label for="deposit-date">Date paid</label>
          <input
            id="deposit-date"
            type="date"
            formControlName="date"
            data-testid="deposit-form-date"
            [attr.aria-invalid]="invalid('date')"
            [attr.aria-describedby]="invalid('date') ? 'deposit-date-error' : null"
          />
          @if (invalid('date')) {
            <p id="deposit-date-error" role="alert" data-testid="deposit-form-date-error">
              Enter the date the deposit was paid.
            </p>
          }
        </div>
        <button type="submit" data-testid="deposit-form-submit" [disabled]="saving()">Record deposit</button>
        @if (saveError()) {
          <p role="alert" data-testid="deposit-form-error">{{ saveError() }}</p>
        }
        @if (saved()) {
          <p role="status" data-testid="deposit-form-recorded">Deposit recorded.</p>
        }
      </form>
    </section>
  `,
})
export class ClientDeposits {
  private readonly service = inject(DepositService);

  readonly clientId = input.required<number>();
  /** The client's currency; their deposits are held in it. */
  readonly currency = input.required<CurrencyCode>();

  protected readonly deposits = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.service.list(params),
  });

  protected readonly saving = signal(false);
  protected readonly saved = signal(false);
  protected readonly saveError = signal<string | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    amount: ['', [Validators.required, Validators.min(0.01), Validators.pattern(TWO_DECIMALS)]],
    date: ['', [Validators.required]],
  });

  protected invalid(name: 'amount' | 'date'): boolean {
    const control = this.form.controls[name];
    return control.invalid && (control.touched || control.dirty);
  }

  /** Loads the deposits again, e.g. after some were put toward invoices elsewhere on the page. */
  reload(): void {
    this.deposits.reload();
  }

  protected submit(): void {
    this.saveError.set(null);
    this.saved.set(false);
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    const { amount, date } = this.form.getRawValue();
    this.saving.set(true);
    this.service.record(this.clientId(), { amount: Number(amount), date }).subscribe({
      next: () => {
        this.saving.set(false);
        this.saved.set(true);
        this.form.reset();
        this.deposits.reload();
      },
      error: () => {
        this.saving.set(false);
        this.saveError.set('Could not record the deposit. Please try again.');
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

/** Money a client paid up front, before any invoice, held against the client. */
export interface Deposit {
  id: number;
  clientId: number;
  amount: number;
  /** ISO date (yyyy-MM-dd) the deposit was paid. */
  date: string;
}

export interface NewDeposit {
  amount: number;
  date: string;
}

/** Part of a client's held deposits to put toward their invoices, split across them. */
export interface NewDepositApplication {
  allocations: { invoiceId: number; amount: number }[];
}

/** The deposits a client has paid, oldest first; `total` is what is still held after `applied` was put toward invoices and `refunded` paid back. */
export interface ClientDeposits {
  total: number;
  applied: number;
  refunded: number;
  deposits: Deposit[];
}

@Injectable({ providedIn: 'root' })
export class DepositService {
  private readonly http = inject(HttpClient);

  list(clientId: number): Observable<ClientDeposits> {
    return this.http.get<ClientDeposits>(`/api/clients/${clientId}/deposits`);
  }

  record(clientId: number, deposit: NewDeposit): Observable<Deposit> {
    return this.http.post<Deposit>(`/api/clients/${clientId}/deposits`, deposit);
  }

  /** Puts part of the client's held deposits toward the given invoices. */
  apply(clientId: number, application: NewDepositApplication): Observable<unknown> {
    return this.http.post(`/api/clients/${clientId}/deposits/applications`, application);
  }
}
import { Pipe, PipeTransform, inject } from '@angular/core';
import { formatNumber, getCurrencySymbol } from '@angular/common';
import { CurrencyService } from './currency.service';

/** Rounds an amount to the nearest multiple of the step (both in whole cents), halves away from zero. */
export function roundToStep(amount: number, step: number): number {
  const stepCents = Math.max(1, Math.round(step * 100));
  const cents = Math.round(Math.abs(amount) * 100);
  return (Math.sign(amount) * Math.round(cents / stepCents) * stepCents) / 100;
}

/**
 * Fits digits info such as '1.2-4' to a currency's decimal places: the minimum fraction digits become the
 * currency's, and the maximum is never fewer than that.
 */
export function digitsFor(digitsInfo: string, decimals: number): string {
  const match = /^(\d+)\.(\d+)-(\d+)$/.exec(digitsInfo);
  if (!match) {
    return digitsInfo;
  }
  return `${match[1]}.${decimals}-${Math.max(decimals, Number(match[3]))}`;
}

/**
 * Shows an amount in a currency: with the currency's symbol and decimal places (none for yen), rounded to
 * the currency's rounding step (e.g. to the nearest five cents) and never finer than its smallest unit.
 * Pass `rounded` false for rates such as unit prices, which are shown as they are. Without explicit digits
 * info an amount is shown with exactly the currency's decimal places. Impure so it picks up the currencies
 * once they load or their rounding changes.
 */
@Pipe({ name: 'money', pure: false })
export class MoneyPipe implements PipeTransform {
  private readonly currencies = inject(CurrencyService);

  transform(value: number | null | undefined, code: string, digitsInfo?: string, rounded = true): string | null {
    if (value === null || value === undefined) {
      return null;
    }
    const currency = this.currencies.find(code);
    const symbol = currency?.symbol ?? getCurrencySymbol(code, 'wide', 'en-US');
    const decimals = currency?.decimals ?? 2;
    const step = Math.max(currency?.roundingStep ?? 0.01, 10 ** -decimals);
    const amount = rounded ? roundToStep(value, step) : value;
    const digits = digitsInfo ? digitsFor(digitsInfo, decimals) : `1.${decimals}-${decimals}`;
    const sign = amount < 0 ? '-' : '';
    return sign + symbol + formatNumber(Math.abs(amount), 'en-US', digits);
  }
}

